import base64
import json
import mimetypes
import os
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _load_image_bytes(image: Any) -> bytes:
    if isinstance(image, (bytes, bytearray)):
        return bytes(image)

    if isinstance(image, str):
        if image.startswith("http://") or image.startswith("https://"):
            import urllib.request

            with urllib.request.urlopen(image) as resp:
                return resp.read()
        if os.path.exists(image):
            with open(image, "rb") as f:
                return f.read()
        try:
            return base64.b64decode(image, validate=True)
        except Exception as e:
            raise ValueError("Unsupported image input string. Provide a file path, URL, or base64 data.") from e

    raise TypeError("image must be bytes, bytearray, file path, URL, or base64 string")


def _image_mime_type(image_path: Optional[str], image_bytes: bytes) -> str:
    if image_path:
        mime, _ = mimetypes.guess_type(image_path)
        if mime:
            return mime
    return "image/jpeg"


def check_image_safety(image: Any) -> Dict[str, Any]:
    """
    Check an image for unsafe or policy-sensitive visual content using Amazon Rekognition.

    Returns a dictionary with:
      - unsafe: bool
      - labels: list of detected labels
      - text: list of detected text
      - moderation_flags: list of policy-sensitive indicators
      - raw: raw service response subset
    """
    image_path = image if isinstance(image, str) and os.path.exists(image) else None
    image_bytes = _load_image_bytes(image)
    mime_type = _image_mime_type(image_path, image_bytes)

    rekognition = boto3.client("rekognition")

    try:
        label_resp = rekognition.detect_labels(
            Image={"Bytes": image_bytes},
            MaxLabels=50,
            MinConfidence=70.0,
        )
        text_resp = rekognition.detect_text(
            Image={"Bytes": image_bytes},
        )
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Amazon Rekognition analysis failed: {e}") from e

    labels = [
        {
            "name": item.get("Name"),
            "confidence": item.get("Confidence"),
            "parent_names": [p.get("Name") for p in item.get("Parents", []) if p.get("Name")],
        }
        for item in label_resp.get("Labels", [])
    ]

    text_detections = [
        {
            "text": item.get("DetectedText"),
            "confidence": item.get("Confidence"),
            "type": item.get("Type"),
        }
        for item in text_resp.get("TextDetections", [])
        if item.get("DetectedText")
    ]

    label_names = {l["name"].lower() for l in labels if l.get("name")}
    text_blob = " ".join(t["text"] for t in text_detections).lower()

    moderation_flags = []

    unsafe_label_rules = {
        "nudity": {"nudity", "explicit", "sexual content"},
        "violence": {"weapon", "gun", "knife", "explosion", "blood", "violence"},
        "self_harm": {"suicide", "self harm", "self-harm", "hanging"},
        "drugs": {"drug", "alcohol", "cigarette", "smoking", "marijuana"},
        "hate_symbols": {"swastika", "racist", "hate symbol"},
        "gore": {"gore", "corpse", "dead body"},
        "illegal_activity": {"cash", "counterfeit", "drug", "bomb"},
    }

    sensitive_text_rules = {
        "phone_number": ["phone", "tel", "+1", "+44"],
        "credit_card": ["visa", "mastercard", "amex", "credit card"],
        "personal_id": ["passport", "driver license", "ssn", "social security"],
    }

    for category, keywords in unsafe_label_rules.items():
        if any(keyword in label_names for keyword in keywords):
            moderation_flags.append(category)

    for category, keywords in sensitive_text_rules.items():
        if any(keyword in text_blob for keyword in keywords):
            moderation_flags.append(category)

    unsafe = len(moderation_flags) > 0

    return {
        "unsafe": unsafe,
        "labels": labels,
        "text": text_detections,
        "moderation_flags": sorted(set(moderation_flags)),
        "raw": {
            "label_detection": {
                "LabelCount": label_resp.get("LabelModelVersion"),
                "Labels": label_resp.get("Labels", []),
            },
            "text_detection": {
                "TextDetections": text_resp.get("TextDetections", []),
            },
            "mime_type": mime_type,
        },
    }
